package com.shopsphere;
import java.math.BigDecimal;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
public interface ProductRepository{
 record Search(List<Product>content,long total){}
 Product save(Product p);Optional<Product>findById(UUID id);Optional<Product>findBySlug(String slug);Optional<Product>findBySku(String sku);List<Product>findAll();List<Product>findAllById(Collection<UUID>ids);List<Product>findRelated(Product product,int limit);void delete(UUID id);Search search(String q,String category,String brand,BigDecimal min,BigDecimal max,Double rating,String sort,int page,int size);
 class InMemory implements ProductRepository{private final Map<UUID,Product>data=new ConcurrentHashMap<>();public Product save(Product p){data.put(p.id(),p);return p;}public Optional<Product>findById(UUID id){return Optional.ofNullable(data.get(id));}public Optional<Product>findBySlug(String s){return data.values().stream().filter(p->p.slug().equalsIgnoreCase(s)).findFirst();}public Optional<Product>findBySku(String s){return data.values().stream().filter(p->p.sku().equalsIgnoreCase(s)).findFirst();}public List<Product>findAll(){return new ArrayList<>(data.values());}public List<Product>findAllById(Collection<UUID>ids){return ids.stream().map(data::get).filter(Objects::nonNull).toList();}public List<Product>findRelated(Product product,int limit){BigDecimal low=product.price().multiply(BigDecimal.valueOf(.5)),high=product.price().multiply(BigDecimal.valueOf(1.5));return data.values().stream().filter(Product::active).filter(p->!p.id().equals(product.id())).filter(p->p.category().equalsIgnoreCase(product.category())).sorted(Comparator.<Product>comparingInt(p->p.price().compareTo(low)>=0&&p.price().compareTo(high)<=0?0:1).thenComparing(Comparator.comparingDouble(Product::rating).reversed())).limit(limit).toList();}public void delete(UUID id){data.remove(id);}public Search search(String q,String category,String brand,BigDecimal min,BigDecimal max,Double rating,String sort,int page,int size){List<String>terms=q==null?List.of():Arrays.stream(q.trim().toLowerCase().split("\\s+")).filter(s->!s.isBlank()).toList();var all=data.values().stream().filter(Product::active).filter(p->{String haystack=(p.name()+" "+p.description()+" "+p.brand()+" "+p.category()).toLowerCase();return terms.stream().allMatch(haystack::contains);}).filter(p->category==null||p.category().equalsIgnoreCase(category.trim())).filter(p->brand==null||p.brand().equalsIgnoreCase(brand.trim())).filter(p->min==null||p.price().compareTo(min)>=0).filter(p->max==null||p.price().compareTo(max)<=0).filter(p->rating==null||p.rating()>=rating).sorted(sorter(sort)).toList();int from=Math.min(page*size,all.size());return new Search(all.subList(from,Math.min(from+size,all.size())),all.size());}private static Comparator<Product>sorter(String s){return switch(s==null?"newest":s){case"price_asc"->Comparator.comparing(Product::price);case"price_desc"->Comparator.comparing(Product::price).reversed();case"rating"->Comparator.comparingDouble(Product::rating).reversed();default->Comparator.comparing(Product::createdAt).reversed();};}}
}
